xlength="5000" required></textarea><p v-if="!portfolio.email" class="form-note">O contato direto está sendo configurado. Você pode copiar sua mensagem abaixo.</p><p v-else class="form-note">Seu aplicativo de e-mail será aberto com a mensagem pronta para enviar.</p><button class="button light" type="submit">{{ portfolio.email ? 'Abrir rascunho de e-mail' : 'Copiar mensagem' }} <span>↗</span></button><p class="form-status" role="status">{{ formStatus }}</p></form></div></section>
