<template>
  <section id="journey" class="journey-scenes" aria-labelledby="journey-heading">
    <div class="section journey-intro">
      <div class="section-label"><span>02 — TRAJETÓRIA</span><span>CONSTRUÍDA UMA ETAPA POR VEZ</span></div>
      <h2 id="journey-heading">Uma base sólida.<br><em>Sempre em evolução.</em></h2>
    </div>
    <div ref="stage" class="journey-stage">
    <article v-for="(chapter, index) in chapters" :key="chapter.number" class="journey-scene" :aria-labelledby="'chapter-' + index">
      <div class="journey-media" aria-hidden="true">
        <template v-if="index === 3">
          <img class="journey-layer study-first" :src="media.first" alt="" loading="lazy">
          <img class="journey-layer study-last" :src="media.last" alt="" loading="lazy">
        </template>
        <video v-else-if="chapter.video" class="journey-layer" :src="chapter.video" :poster="chapter.poster" muted playsinline loop preload="none" tabindex="-1" @playing="videoBlocked = false"></video>
        <img v-else class="journey-layer" :src="chapter.image" alt="" loading="lazy">
      </div>
      <div class="journey-shade" aria-hidden="true"></div>
      <div class="journey-content">
        <div class="journey-meta"><span>{{ chapter.date }}</span><span>{{ chapter.number }} / 04</span></div>
        <div class="journey-copy">
          <h3 :id="'chapter-' + index">{{ chapter.title }}</h3>
          <h4>{{ chapter.subtitle }}</h4>
          <p v-for="paragraph in chapter.paragraphs" :key="paragraph">{{ paragraph }}</p>
        </div>
        <div class="journey-bottom">
          <span>{{ index === 3 ? 'PROJETOS / APRENDIZADO' : chapter.label }}</span>
          <button v-if="chapter.video" type="button" :aria-pressed="String(paused)" @click="togglePlayback">{{ paused || videoBlocked ? 'Reproduzir fundo' : 'Pausar fundo' }}</button>
        </div>
      </div>
      <div class="journey-progress" aria-hidden="true"><span></span></div>
    </article>
    </div>
  </section>
</template>

<script>
import { gsap } from 'gsap'
import { ScrollTrigger } from 'gsap/ScrollTrigger'
import hardware from '../assets/journey/hardware.mp4'
import hardwarePoster from '../assets/journey/hardware-poster.jpg'
import award from '../assets/journey/award.mp4'
import awardPoster from '../assets/journey/award-poster.jpg'
import hion from '../assets/journey/hion.jpg'
import first from '../assets/journey/study-first.jpg'
import last from '../assets/journey/study-last.jpg'

gsap.registerPlugin(ScrollTrigger)
export default {
  name: 'JourneyScenes',
  data: () => ({
    paused: false, videoBlocked: false, active: -1,
    media: { first, last },
    chapters: [
      { number: '01', date: 'FORMAÇÃO TÉCNICA', label: 'ELETRÔNICA / AUTOMAÇÃO', video: hardware, poster: hardwarePoster, title: 'Onde o código encontra o hardware.', subtitle: 'ETEC Júlio de Mesquita · Automação Industrial', paragraphs: ['Concluí o Ensino Médio integrado ao curso Técnico em Automação Industrial. Desenvolvi experiência prática em eletrônica, programação embarcada, automação e integração de software com dispositivos inteligentes.'] },
      { number: '02', date: '2023', label: 'TOMADA INTELIGENTE / INOVAÇÃO', video: award, poster: awardPoster, title: 'Uma ideia que conquistou reconhecimento.', subtitle: 'Tomada Inteligente · Trabalho de Conclusão de Curso', paragraphs: ['Desenvolvi a “Tomada Inteligente”, um protótipo para telemetria de energia elétrica residencial. O projeto foi apresentado na Semana Municipal de Ciência e Tecnologia de Santo André e conquistou o segundo lugar.'] },
      { number: '03', date: 'JUL 2024 — ATUALMENTE', label: 'SOFTWARE / SISTEMAS CONECTADOS', image: hion, title: 'Desenvolvendo para o mundo real.', subtitle: 'HION · Programador de Sistemas da Informação', paragraphs: ['Desenvolvo, mantenho e evoluo sistemas corporativos e industriais, dos requisitos à implantação. Construo serviços em Node.js e interfaces em Vue.js e React, integro APIs HTTP e gRPC, modelo bancos de dados e opero microsserviços em contêineres.', 'Atuo em aplicações ERP e IoT para web, computadores e dispositivos móveis, com gestão de usuários, monitoramento operacional e métricas de sistemas. Também desenvolvo e integro uma plataforma de gestão de todos os processos em diversos varejos. Aplico análise de dados e redes LSTM à previsão da vida útil de baterias industriais.'] },
      { number: '04', date: 'EM ANDAMENTO', label: 'CIÊNCIA DA COMPUTAÇÃO', title: 'Aprofundando os fundamentos.', subtitle: 'Ciência da Computação · Ênfase em Desenvolvimento de Software', paragraphs: ['Estou em fase de conclusão da graduação, aprofundando minha base em matemática, estruturas de dados e algoritmos para IA. Exploro métodos numéricos, álgebra linear, otimização, CNNs e LSTMs em conjunto com a prática em engenharia de software.'] }
    ]
  }),
  mounted() {
    this.scenes = Array.from(this.$el.querySelectorAll('.journey-scene'))
    this.reducedQuery = window.matchMedia('(prefers-reduced-motion: reduce)')
    this.paused = this.reducedQuery.matches
    this.onPreference = () => { this.paused = this.reducedQuery.matches; this.syncPlayback() }
    this.reducedQuery.addEventListener('change', this.onPreference)
    this.onVisibility = () => this.syncPlayback()
    document.addEventListener('visibilitychange', this.onVisibility)
    this.sceneVisibility = new Map()
    this.observer = new IntersectionObserver(entries => {
      if (this.pinned) return
      entries.forEach(entry => this.sceneVisibility.set(entry.target, entry.intersectionRatio))
      let best = -1
      let ratio = 0.15
      this.scenes.forEach((scene, index) => {
        const visible = this.sceneVisibility.get(scene) || 0
        if (visible > ratio) { ratio = visible; best = index }
      })
      if (best !== this.active) {
        this.active = best
        this.videoBlocked = false
        this.syncPlayback()
      }
    }, { threshold: Array.from({ length: 21 }, (_, index) => index / 20) })
    this.scenes.forEach(scene => this.observer.observe(scene))
    this.motion = gsap.matchMedia()
    this.motion.add('(prefers-reduced-motion: no-preference) and (min-height: 700px)', () => {
      const stage = this.$refs.stage
      this.pinned = true
      stage.classList.add('is-pinned')
      gsap.set(this.scenes, { autoAlpha: 0 })
      gsap.set(this.scenes[0], { autoAlpha: 1 })
      let timeline
      timeline = gsap.timeline({
        scrollTrigger: {
          trigger: stage, start: 'top top', end: () => '+=' + window.innerHeight * 7,
          // Measure after the welcome section has reserved its pin spacing.
          refreshPriority: -1,
          pin: true, scrub: 0.7, invalidateOnRefresh: true, anticipatePin: 1,
          onToggle: self => {
            this.inStage = self.isActive
            this.updatePinnedScene(timeline ? timeline.time() : 0)
          }
        },
        onUpdate: () => this.updatePinnedScene(timeline ? timeline.time() : 0)
      })
      this.scenes.slice(1).forEach((scene, offset) => {
        const start = (offset + 1) * 2 - 0.5
        timeline.to(this.scenes[offset], { autoAlpha: 0, duration: 0.5, ease: 'none' }, start)
          .to(scene, { autoAlpha: 1, duration: 0.5, ease: 'none' }, start)
      })
      // The fourth chapter keeps its text still while the two photographs blend.
      timeline.to(stage.querySelector('.study-last'), { opacity: 1, duration: 0.8, ease: 'none' }, 7.2)
      timeline.to({}, { duration: 1 }, 8)
      // Progress shares the same scroll range as the chapter animation.
      timeline.fromTo(stage.querySelectorAll('.journey-progress span'), { scaleX: 0 }, {
        scaleX: 1, duration: 9, ease: 'none'
      }, 0)
      return () => {
        this.pinned = false
        this.inStage = false
        stage.classList.remove('is-pinned')
        this.scenes.forEach(scene => { scene.removeAttribute('inert'); scene.removeAttribute('aria-hidden') })
        this.active = -1
        this.syncPlayback()
        this.sceneVisibility.clear()
        this.observer.disconnect()
        this.scenes.forEach(scene => this.observer.observe(scene))
      }
    })
    this.$nextTick(() => { ScrollTrigger.refresh(); this.syncPlayback() })
  },
  beforeDestroy() {
    if (this.motion) this.motion.revert()
    if (this.observer) this.observer.disconnect()
    this.$el.querySelectorAll('video').forEach(video => video.pause())
    document.removeEventListener('visibilitychange', this.onVisibility)
    if (this.reducedQuery) this.reducedQuery.removeEventListener('change', this.onPreference)
  },
  methods: {
    updatePinnedScene(time) {
      const selected = Math.min(3, Math.floor((time + 0.25) / 2))
      this.scenes.forEach((scene, index) => {
        scene.toggleAttribute('inert', index !== selected)
        scene.setAttribute('aria-hidden', String(index !== selected))
      })
      const active = this.inStage ? selected : -1
      if (active !== this.active) { this.active = active; this.videoBlocked = false; this.syncPlayback() }
    },
    playVideo(video) {
      video.muted = true
      const playing = video.play()
      if (playing) playing.catch(error => { if (error.name !== 'AbortError') this.videoBlocked = true })
    },
    syncPlayback() {
      const running = !this.paused && !document.hidden
      this.scenes.forEach((scene, index) => scene.querySelectorAll('video').forEach(video => {
        if (running && index === this.active) this.playVideo(video)
        else video.pause()
      }))
    },
    togglePlayback() {
      if (this.videoBlocked) { this.videoBlocked = false; this.paused = false }
      else this.paused = !this.paused
      this.syncPlayback()
    }
  }
}
</script>

