.journey-shade{z-index:-2;background:linear-gradient(90deg,rgba(4,8,17,.9),rgba(4,8,17,.7) 42%,rgba(4,8,17,.15) 80%),linear-gradient(0deg,rgba(4,8,17,.8),transparent 35%,rgba(4,8,17,.25))}
.journey-content{width:100%;min-height:100svh;padding:44px 7% 30px;display:flex;flex-direction:column;justify-content:space-between;gap:44px}.journey-meta,.journey-bottom{display:flex;justify-content:space-between;align-items:center;gap:20px;color:#e0e8fa;font:.875rem/1.6 'IBM Plex Mono',monospace;letter-spacing:.06em}.journey-meta>span:last-child{color:#b3c6ff;white-space:nowrap}.journey-copy{max-width:690px;padding:30px 0}.journey-copy h3{font-size:clamp(2.25rem,4.5vw,4.8rem);line-height:1.07;letter-spacing:-.045em;margin-bottom:26px;text-wrap:balance;color:#fff}.journey-copy h4{font-size:1rem;line-height:1.6;font-weight:500;color:#bed0ff;margin-bottom:22px}.journey-copy p{max-width:610px;font-size:1.0625rem;line-height:1.8;color:#eef1f8;text-shadow:0 1px 12px #000}.journey-copy p:last-child{margin-bottom:0}.journey-bottom button{background:#0a1228b3;border:1px solid #ffffff70;border-radius:30px;color:#fff;font-size:.875rem;padding:12px 20px;letter-spacing:0;flex-shrink:0}.journey-bottom button:hover{background:#234085}.journey-progress{position:absolute;bottom:0;left:0;right:0;height:3px;background:#ffffff22}.journey-progress span{display:block;height:100%;background:#91adff;transform-origin:left}
@media(min-width:1500px){.journey-copy{max-width:760px}}
@media(max-width:700px){.journey-content{padding:30px 6% 24px;gap:30px}.journey-copy{padding:24px 0}.journey-copy h3{font-size:clamp(2.1rem,9vw,3.5rem)}.journey-copy p{font-size:1rem;line-height:1.7}.journey-meta,.journey-bottom{font-size:.75rem;letter-spacing:.03em}.journey-bottom{flex-wrap:wrap}.journey-shade{background:linear-gradient(0deg,#040811ed,rgba(4,8,17,.68) 65%,rgba(4,8,17,.28))}.journey-layer{object-position:center}}
@media(prefers-reduced-motion:reduce){.journey-progress{display:none}}
/* One pinned screen; chapters dissolve without translating their text. */
.journey-stage.is-pinned{height:100svh;position:relative;isolation:isolate;background:#050810;overflow:hidden}
.is-pinned .journey-scene{position:absolute;inset:0;min-height:0;height:100%;border:0}
.is-pinned .journey-content{height:100%;min-height:0;padding-top:28px;padding-bottom:24px;gap:18px}
.is-pinned .journey-copy{padding:12px 0}
.is-pinned .journey-copy h3{font-size:clamp(2rem,4vw,4rem);margin-bottom:20px}
.is-pinned .journey-copy p{line-height:1.65}
@media(max-width:700px){.is-pinned .journey-copy h3{font-size:clamp(1.8rem,7.5vw,2.7rem)}.is-pinned .journey-copy h4{margin-bottom:14px}.is-pinned .journey-copy p{font-size:1rem;line-height:1.5}.is-pinned .journey-content{gap:12px;padding:22px 6%}.is-pinned .journey-copy{padding:0}}
/* Short screens and reduced motion retain a readable, unpinned document. */
.journey-stage:not(.is-pinned) .study-last{top:auto;bottom:0;height:65svh;opacity:1}
.journey-stage:not(.is-pinned) .journey-scene:last-child{padding-bottom:65svh}
.journey-stage:not(.is-pinned) .journey-scene:last-child .journey-media{overflow:hidden}
</style>
